  <div class="meta">${c ? `<a href="#cust/${c.id}"><b>${H(c.name)}</b></a> · ` : '<span class="tag w">عميل مش محدد</span> · '}إلى <b dir="ltr">${H(t.recipient || '—')}</b> ${t.recipient ? `<button class="g" style="min-height:28px;padding:2px 8px" onclick="A.copy('${H(t.recipient)}')">${ic('copy')}</button>` : ''} · ${H(t.walletId ? wName(t.walletId) : provName(t.provider))}${t.commission != null && t.executedAt ? ` · عمولة ${M(t.commission)} · رسوم ${M(t.fee)}` : ''}${t.ref ? ` · مرجع <span dir="ltr">${H(t.ref)}</span>` : ''}</div>
