  const sh = $('#spSh'); if (sh) sh.onclick = async () => { const f = new File([blob.blob], 'proof-' + t.no + '.jpg', { type: blob.blob.type || 'image/jpeg' }); const d = { files: [f], text: val('spT') }; if (navigator.canShare(d)) { try { await navigator.share(d); } catch (e) { } } else toast('الجهاز ده مابيدعمش مشاركة الصور', 'r'); };
