/* =================== الإثباتات + OCR =================== */
let OCR = null;
function loadTess() { if (window.Tesseract) return Promise.resolve(); return new Promise((ok, no) => { const s = document.createElement('script'); s.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js'; s.onload = ok; s.onerror = () => no(new Error('مكتبة قراية الصور ماحمّلتش — محتاج نت أول مرة')); document.head.appendChild(s); }); }
async function ocrWorker() { if (OCR) return OCR; await loadTess(); OCR = await Tesseract.createWorker(['ara', 'eng']); return OCR; }
async function sha(blob) { const b = await blob.arrayBuffer(); const h = await crypto.subtle.digest('SHA-256', b); return [...new Uint8Array(h)].map(x => x.toString(16).padStart(2, '0')).join(''); }
async function shrink(file) { try { const u = URL.createObjectURL(file), im = await new Promise((ok, no) => { const i = new Image(); i.onload = () => ok(i); i.onerror = no; i.src = u; }); const k = Math.min(1, 1600 / Math.max(im.width, im.height)), c = document.createElement('canvas'); c.width = Math.round(im.width * k); c.height = Math.round(im.height * k); c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); return await new Promise(r => c.toBlob(r, 'image/jpeg', .85)); } catch (e) { return file; } }
const QUEUE = {};
async function importImages(files, forTx) {
  for (const f of files) {
    if (!/^image\//.test(f.type)) { toast('ده مش صورة: ' + f.name, 'r'); continue; }
    const hash = await sha(f), dupe = Object.values(S.proofs).find(p => p.hash === hash);
    if (dupe && !window.confirm('الصورة دي اتستوردت قبل كده' + (dupe.txId && S.tx[dupe.txId] ? ' ومربوطة بالعملية ' + S.tx[dupe.txId].no : '') + ' — تضيفها تاني؟')) continue;
    const id = C.uid(), blob = await shrink(f); await dbPut('blobs', { id, blob, name: f.name, at: nowIso() });
    await dispatch('proof.add', { id, hash, name: f.name, size: f.size, status: 'ocr', forTx: forTx || null, ext: {} }); QUEUE[id] = 0; runOcr(id, blob, forTx);
  }
}
async function runOcr(id, blob, forTx) {
  try { const w = await ocrWorker(); const r = await w.recognize(blob); const text = r.data.text || ''; const ext = C.extractProof(text, ST().providers);
    await dispatch('proof.update', { id, ocrText: text, ext, status: 'ready' });
    const p = S.proofs[id];
    if (forTx && S.tx[forTx]) { await linkProof(id, forTx, 100, ['اترفعت من على العملية نفسها']); }
    else { const m = C.matchProof(S, ext, p.createdAt); await dispatch('proof.update', { id, cands: m.candidates, suggested: m.suggested, ambiguous: m.ambiguous }); }
    if (ext.ref) { const d = C.refExists(S, ext.ref, forTx); if (d && d.id !== forTx) toast('تحذير: رقم المرجع ' + ext.ref + ' متسجل على ' + d.no, 'r'); }
  } catch (e) { await dispatch('proof.update', { id, status: 'error', err: String(e.message || e) }); toast('ماقدرتش أقرا الصورة: ' + (e.message || e), 'r'); }
  delete QUEUE[id]; if (ROUTE === 'inbox' || ROUTE === 'ops') paint();
}
async function linkProof(pid, txId, score, why) { const t = S.tx[txId], other = Object.values(S.proofs).find(p => p.txId === txId && p.id !== pid); if (t.status === 'completed' && other && !window.confirm('العملية دي مكتملة ومربوط بيها إثبات تاني — تربط الصورة دي كمان؟')) return;
  await dispatch('proof.link', { id: pid, txId, score, why }); const p = S.proofs[pid];
  if (p.ext && p.ext.ref) { const d = C.refExists(S, p.ext.ref, txId); if (d) await dispatch('tx.status', { id: txId, status: 'review', reason: 'رقم مرجع الصورة متسجل على ' + d.no }); }
  if (p.ext && p.ext.amount && p.ext.amount !== t.amount) toast('المبلغ في الصورة (' + M(p.ext.amount) + ') مختلف عن العملية (' + M(t.amount) + ') — راجعها', 'r'); else toast('اتربطت الصورة بالعملية ' + t.no, 'g'); }
V.inbox = () => { const P = Object.values(S.proofs).sort((a, b) => b.createdAt > a.createdAt ? 1 : -1), un = P.filter(p => !p.txId && !p.ignored), linked = P.filter(p => p.txId).slice(0, 20);
  return `<h1>${ic('inbox')} الإثباتات <span class="sp"></span><button onclick="document.getElementById('pfIn').click()">${ic('image')}استيراد صور</button><button class="s" onclick="document.getElementById('pfCam').click()">${ic('cam')}تصوير</button></h1>
  <input type="file" id="pfIn" accept="image/*" multiple hidden onchange="A.importImages([...this.files]);this.value=''"><input type="file" id="pfCam" accept="image/*" capture="environment" hidden onchange="A.importImages([...this.files]);this.value=''">
  <div class="card muted" style="font-size:13px;line-height:1.9">السيستم بيقرا الصورة على الجهاز (من غير ما تترفع لأي حتة): المبلغ، رقم العملية، التاريخ والوقت، الأرقام، المحفظة، والحالة — وبيقترح العملية المناسبة. <b>الصورة إثبات مصوَّر بس</b> — التأكيد النهائي منك.</div>
  <h3 style="margin:14px 0 8px">مش مربوطة (${N(un.length)})</h3>${un.map(proofCard).join('') || '<div class="card empty">كل الإثباتات مربوطة</div>'}
  ${linked.length ? `<h3 style="margin:14px 0 8px">آخر المربوطة</h3>${linked.map(proofCard).join('')}` : ''}`; };
V.inbox.after = () => loadThumbs();
function proofCard(p) { const e = p.ext || {}, t = p.txId && S.tx[p.txId], dupH = Object.values(S.proofs).filter(x => x.hash === p.hash).length > 1, dupR = e.ref && C.refExists(S, e.ref, p.txId);
  return `<div class="tx" style="--c:${t ? 'var(--ok)' : 'var(--warn)'}"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><img class="thumb" data-blob="${p.id}" onclick="A.viewProof('${p.id}')" alt=""><div style="flex:1;min-width:0">
  ${p.status === 'ocr' ? `<b>بيقرا الصورة…</b><div class="prog" style="margin-top:6px"><i style="width:60%"></i></div>` : p.status === 'error' ? `<b class="neg">ماقدرش يقرا الصورة</b><div class="meta">${H(p.err || '')}</div>` : `<div class="kv" style="font-size:13px"><span>المبلغ</span><b>${e.amount ? M(e.amount) : '—'}</b><span>المرجع</span><b dir="ltr">${H(e.ref || '—')}</b><span>المستلم</span><b dir="ltr">${H(e.recipient || e.recipientName || '—')}</b><span>الوقت</span><b>${H((e.date || '') + ' ' + (e.time || ''))}</b><span>الخدمة / الحالة</span><b>${H(provName(e.provider))} · ${H(e.status || '—')}</b></div>`}
  ${dupH ? `<div class="alert r" style="margin:6px 0 0">${ic('alert')}صورة متكررة</div>` : ''}${dupR && (!t || dupR.id !== t.id) ? `<div class="alert r" style="margin:6px 0 0">${ic('alert')}رقم المرجع متسجل على ${H(dupR.no)}</div>` : ''}
  ${t ? `<div class="meta">مربوطة بـ <b>${H(t.no)}</b> — ${M(t.amount)} إلى <span dir="ltr">${H(t.recipient)}</span> ${p.linkScore ? `(تطابق ${N(p.linkScore)}٪)` : ''}</div><div class="acts"><button class="g" onclick="A.unlink('${p.id}')">${ic('link')}فك الربط</button></div>` :
    p.status === 'ready' ? `<div style="margin-top:8px">${(p.cands || []).length ? (p.cands.map(c => { const x = S.tx[c.txId]; return x ? `<div class="row" style="border:1px solid var(--line);border-radius:10px;padding:6px 8px;margin-top:6px"><div class="f"><b>${H(x.no)}</b> · ${M(x.amount)} → <span dir="ltr">${H(x.recipient)}</span> · ${H((cust(x.customerId) || {}).name || '')}<div class="meta">تطابق ${N(c.score)}٪: ${H(c.why.join('، '))}</div></div><button class="${p.suggested === c.txId ? '' : 's'}" onclick="A.link('${p.id}','${c.txId}',${c.score})">${ic('link')}${p.suggested === c.txId ? 'ربط (مقترح)' : 'ربط'}</button></div>` : ''; }).join('') + (p.ambiguous ? `<div class="alert" style="margin-top:6px">${ic('alert')}فيه أكتر من عملية محتملة — اختار بنفسك</div>` : '')) : '<div class="muted">مالقيتش عملية مفتوحة مطابقة</div>'}
    <div class="acts"><button class="s" onclick="A.pickTx('${p.id}')">${ic('search')}اختار عملية بنفسي</button><button class="s" onclick="A.reqFromProof('${p.id}')">${ic('plus')}اعمل عملية منها</button><button class="g" onclick="A.editExt('${p.id}')">${ic('edit')}صحح البيانات</button><button class="g" onclick="A.ignoreProof('${p.id}')">${ic('x')}تجاهل</button></div></div>` : ''}</div></div></div>`; }
async function viewProof(id) { const b = await getBlob(id), p = S.proofs[id]; if (!b) return toast('الصورة مش موجودة على الجهاز ده', 'r'); const u = URL.createObjectURL(b.blob);
  modal(`<h3>${ic('image')} صورة الإثبات</h3><div class="row" style="align-items:flex-start"><img src="${u}" style="max-width:100%;max-height:70vh;border-radius:12px;border:1px solid var(--line)"><div class="f"><b>النص المقروء</b><pre style="white-space:pre-wrap;font:13px/1.7 Cairo,monospace;background:var(--bg);padding:8px;border-radius:10px;max-height:60vh;overflow:auto">${H(p.ocrText || '—')}</pre></div></div><div class="row"><button class="g" onclick="A.closeM()">إغلاق</button></div>`, 'xl'); }
function pickTx(pid) { const open = Object.values(S.tx).filter(t => !C.DEAD.includes(t.status)).sort((a, b) => b.createdAt > a.createdAt ? 1 : -1).slice(0, 80);
  modal(`<h3>${ic('search')} اختار العملية</h3><input id="ptQ" placeholder="بحث بالمبلغ أو الرقم أو الاسم" oninput="[...document.querySelectorAll('.ptR')].forEach(r=>r.style.display=r.textContent.includes(this.value)?'':'none')"><div style="max-height:60vh;overflow:auto;margin-top:8px">${open.map(t => `<div class="row ptR" style="border-bottom:1px solid var(--line);padding:6px 0"><div class="f"><b>${H(t.no)}</b> ${M(t.amount)} → <span dir="ltr">${H(t.recipient)}</span> · ${H((cust(t.customerId) || {}).name || '')} · ${stTag(t.status)}</div><button class="s" onclick="A.closeM();A.link('${pid}','${t.id}',0)">${ic('link')}ربط</button></div>`).join('')}</div>`); }
function editExt(pid) { const p = S.proofs[pid], e = p.ext || {}; modal(`<h3>${ic('edit')} تصحيح بيانات الصورة</h3><div class="fg"><div><label>المبلغ</label><input id="xA" value="${e.amount ? C.fromP(e.amount) : ''}"></div><div><label>رقم المرجع</label><input id="xR" dir="ltr" value="${H(e.ref || '')}"></div><div><label>رقم المستلم</label><input id="xP" dir="ltr" value="${H(e.recipient || '')}"></div><div><label>الخدمة</label><select id="xS"><option value="">—</option>${ST().providers.map(x => `<option value="${x.key}" ${e.provider === x.key ? 'selected' : ''}>${H(x.name)}</option>`).join('')}</select></div></div><div class="row" style="margin-top:12px"><button id="xGo">${ic('check')}حفظ وإعادة المطابقة</button></div>`);
  $('#xGo').onclick = async () => { const ext = Object.assign({}, e, { amount: C.toP(val('xA')), ref: val('xR').trim(), recipient: C.normPhone(val('xP')), provider: val('xS') }); const m = C.matchProof(S, ext, p.createdAt); await dispatch('proof.update', { id: pid, ext, cands: m.candidates, suggested: m.suggested, ambiguous: m.ambiguous, edited: true }); closeM(); }; }
async function reqFromProof(pid) { const e = S.proofs[pid].ext || {}; reqForm({ amount: e.amount, recipient: e.recipient, provider: e.provider }); }

/* =================== العملاء =================== */
V.customers = () => { const L = C.ledgers(S), list = Object.values(S.customers).sort((a, b) => ((L.parties[b.id] || {}).balance || 0) - ((L.parties[a.id] || {}).balance || 0));
  return `<h1>${ic('users')} العملاء <span class="sp"></span><button onclick="A.custForm()">${ic('plus')}عميل جديد</button></h1><div class="card" style="padding:10px"><input placeholder="بحث بالاسم أو أي رقم" oninput="[...document.querySelectorAll('.cuR')].forEach(r=>r.style.display=r.dataset.k.includes(A.norm(this.value))?'':'none')"></div>
  <div class="card sc"><table><tr><th>العميل</th><th>النوع</th><th>العمليات</th><th>المحوّل</th><th>العمولات</th><th>اتحصل</th><th>الرصيد</th><th>الحالة</th></tr>${list.map(c => { const l = L.parties[c.id] || { count: 0, amount: 0, commission: 0, paid: 0, balance: 0 };
    return `<tr class="cuR" data-k="${H(c.name + ' ' + c.phones.join(' '))}" style="cursor:pointer" onclick="location.hash='cust/${c.id}'"><td><b>${H(c.name)}</b><br><small class="muted" dir="ltr">${H(c.phones.map(C.maskPhone).join(' · '))}</small></td><td>${H(c.type)}${c.group ? `<br><small class="muted">${H(c.group)}</small>` : ''}</td><td>${N(l.count)}</td><td>${M(l.amount)}</td><td>${M(l.commission)}</td><td>${M(l.paid)}</td><td><b class="${l.balance > 0 ? 'neg' : l.balance < 0 ? 'pos' : ''}">${M(l.balance)}</b>${c.credit && l.balance > c.credit ? '<br><span class="tag r">عدّى الحد</span>' : ''}</td><td>${c.status === 'active' ? '<span class="tag">نشط</span>' : c.status === 'review' ? '<span class="tag w">يحتاج مراجعة</span>' : '<span class="tag r">موقوف</span>'}</td></tr>`; }).join('') || '<tr><td colspan="8" class="empty">مفيش عملاء — بيتضافوا لوحدهم من الطلبات أو من «عميل جديد»</td></tr>'}</table></div>`; };
function custForm(id) { const c = id ? cust(id) : { name: '', phones: [], type: 'فرد', terms: 'after', status: 'active' };
  modal(`<h3>${ic('user')} ${id ? 'تعديل ' + H(c.name) : 'عميل جديد'}</h3><div class="fg"><div><label>الاسم</label><input id="cfN" value="${H(c.name)}"></div><div><label>النوع</label><select id="cfT">${['فرد', 'تاجر', 'وسيط', 'شركة'].map(x => `<option ${c.type === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div>
  <div class="full"><label>أرقام الموبايل (رقم في كل سطر — الأول هو الأساسي)</label><textarea id="cfP" dir="ltr" style="min-height:70px">${H(c.phones.join('\n'))}</textarea></div>
  <div><label>فئة العمولة (للقواعد)</label><input id="cfG" value="${H(c.group || '')}" placeholder="مثلاً: تاجر، VIP"></div><div><label>طريقة التحصيل</label><select id="cfM">${[['prepaid', 'بيدفع مقدم'], ['after', 'بيدفع بعد التنفيذ'], ['eod', 'بيسدد آخر اليوم'], ['broker', 'وسيط بنحصّل منه']].map(([k, l]) => `<option value="${k}" ${c.terms === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
  <div><label>الحد الائتماني (اختياري)</label><input id="cfC" inputmode="decimal" value="${c.credit ? C.fromP(c.credit) : ''}"></div><div><label>الحالة</label><select id="cfS">${[['active', 'نشط'], ['review', 'يحتاج مراجعة'], ['stopped', 'موقوف']].map(([k, l]) => `<option value="${k}" ${c.status === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
  <div class="full"><label>ملاحظات</label><input id="cfX" value="${H(c.notes || '')}"></div></div><div class="row" style="margin-top:12px"><button id="cfGo">${ic('check')}حفظ</button><button class="g" onclick="A.closeM()">رجوع</button></div>`);
  $('#cfGo').onclick = async () => { const name = val('cfN').trim(), phones = val('cfP').split(/[\n,،]+/).map(C.normPhone).filter(Boolean); if (!name) return toast('اكتب الاسم', 'r'); if (!phones.length) return toast('اكتب رقم واحد على الأقل', 'r');
    for (const p of phones) { const o = S.phoneIndex[p]; if (o && o !== id) return toast('الرقم ' + p + ' مربوط بعميل تاني: ' + cust(o).name, 'r'); }
    const nid = id || C.uid(); await dispatch('cust.upsert', { id: nid, name, phones, type: val('cfT'), group: val('cfG').trim(), terms: val('cfM'), credit: C.toP(val('cfC')), status: val('cfS'), notes: val('cfX'), temp: false }); closeM(); toast('اتحفظ', 'g'); if (!id) location.hash = 'cust/' + nid; }; }
V.cust = id => { const c = cust(id); if (!c) return '<div class="card empty">العميل مش موجود</div>'; const L = C.ledgers(S), l = L.parties[id] || { count: 0, amount: 0, commission: 0, paid: 0, balance: 0, open: [] };
  const rows = []; Object.values(S.tx).filter(t => t.customerId === id).forEach(t => rows.push({ t: t.executedAt || t.createdAt, kind: 'tx', o: t })); Object.values(S.colls).filter(k => k.partyId === id).forEach(k => rows.push({ t: k.date || k.createdAt, kind: 'coll', o: k }));
  rows.sort((a, b) => a.t < b.t ? -1 : 1); let run = 0;
  const body = rows.map(r => { if (r.kind === 'tx') { const t = r.o, eff = C.isEffective(t), due = eff ? t.amount + (t.commission || 0) : 0; run += due; return `<tr><td>${T(r.t)}</td><td>${H(t.no)} ${stTag(t.status)}</td><td>تحويل ${M(t.amount)} → <span dir="ltr">${H(t.recipient)}</span>${t.commission ? ' + عمولة ' + M(t.commission) : ''}</td><td>${eff ? M(due) : '—'}</td><td></td><td><b>${M(run)}</b></td></tr>`; }
    const k = r.o; if (!k.reversed) run -= k.amount; return `<tr ${k.reversed ? 'style="opacity:.5"' : ''}><td>${T(r.t)}</td><td>تحصيل ${k.reversed ? '<span class="tag r">ملغي</span>' : ''}</td><td>${k.method === 'wallet' ? 'على ' + H(wName(k.walletId)) : 'كاش'}${k.note ? ' · ' + H(k.note) : ''}</td><td></td><td>${M(k.amount)}</td><td><b>${M(run)}</b></td></tr>`; }).reverse().join('');
  const stmt = `كشف حساب ${c.name} — ${ST().name}\nعدد العمليات: ${l.count}\nإجمالي المحوّل: ${M(l.amount)}\nالعمولات: ${M(l.commission)}\nاتدفع: ${M(l.paid)}\nالمتبقي: ${M(l.balance)}`;
  return `<h1>${ic('user')} ${H(c.name)} <span class="tag">${H(c.type)}</span>${c.status !== 'active' ? `<span class="tag w">${c.status === 'review' ? 'يحتاج مراجعة' : 'موقوف'}</span>` : ''}<span class="sp"></span><button class="s" onclick="A.custForm('${id}')">${ic('edit')}تعديل</button><button class="w" onclick="A.collect('${id}')">${ic('cash')}تسجيل تحصيل</button><button onclick="A.newReq('${id}')">${ic('plus')}طلب</button></h1>
  <div class="grid">${kpi('ops', 'العمليات', N(l.count))}${kpi('wallet', 'إجمالي المحوّل', M(l.amount), 'var(--sky)')}${kpi('bolt', 'العمولات', M(l.commission))}${kpi('cash', 'اتحصل', M(l.paid))}${kpi('alert', l.balance >= 0 ? 'عليه' : 'له عندنا', M(Math.abs(l.balance)), l.balance > 0 ? 'var(--bad)' : 'var(--ok)', '', c.credit ? 'الحد ' + M(c.credit) : '')}</div>
  <div class="card"><div class="kv"><span>الأرقام</span><b dir="ltr">${H(c.phones.join(' · '))}</b><span>أول تعامل</span><b>${T(c.createdAt)}</b><span>طريقة التحصيل</span><b>${H({ prepaid: 'مقدم', after: 'بعد التنفيذ', eod: 'آخر اليوم', broker: 'وسيط' }[c.terms] || '')}</b>${c.notes ? `<span>ملاحظات</span><b>${H(c.notes)}</b>` : ''}</div><div class="row" style="margin-top:10px"><a class="btn b" target="_blank" href="${waLink(c.phones[0], stmt)}">${ic('wa')}ابعتله كشف الحساب</a><button class="g" onclick="window.print()">${ic('print')}طباعة</button></div></div>
  <div class="card sc"><b>كشف الحساب</b><table style="margin-top:8px"><tr><th>الوقت</th><th>البند</th><th>التفاصيل</th><th>عليه</th><th>دفع</th><th>الرصيد</th></tr>${body || '<tr><td colspan="6" class="empty">مفيش حركات</td></tr>'}</table></div>`; };

/* =================== التحصيل =================== */
function collect(partyId, txId) { if (!need('collect')) return; const L = C.ledgers(S), parties = Object.values(S.customers); const sel = partyId || '';
  const openOf = pid => (L.parties[pid] || { open: [] }).open; const ws = Object.values(S.wallets).filter(w => w.status !== 'archived');
  modal(`<h3>${ic('cash')} تسجيل تحصيل</h3><div class="fg"><div class="full"><label>من مين</label><select id="koP">${parties.map(c => `<option value="${c.id}" ${c.id === sel ? 'selected' : ''}>${H(c.name)} — عليه ${M((L.parties[c.id] || {}).balance || 0)}</option>`).join('')}</select></div>
  <div><label>المبلغ</label><input id="koA" inputmode="decimal"></div><div><label>طريقة الدفع</label><select id="koM"><option value="cash">كاش في الخزنة</option>${ws.map(w => `<option value="w:${w.id}">تحويل على ${H(w.name)}</option>`).join('')}</select></div>
  <div><label>التاريخ والوقت</label><input id="koD" type="datetime-local" value="${new Date(Date.now() - new Date().getTimezoneOffset() * 6e4).toISOString().slice(0, 16)}"></div><div><label>ملاحظات</label><input id="koN"></div></div>
  <label>توزيع المبلغ</label><div id="koO"></div><div class="row" style="margin-top:12px"><button id="koGo">${ic('check')}تسجيل التحصيل</button><button class="g" onclick="A.closeM()">رجوع</button></div>`);
  const drawOpen = () => { const o = openOf(val('koP')); $('#koO').innerHTML = o.length ? `<div class="muted" style="font-size:13px">من غير اختيار: بيتخصم من الأقدم للأحدث. أو حدد عمليات بعينها:</div>${o.map(x => { const t = S.tx[x.txId]; return `<label style="display:flex;gap:8px;align-items:center;font-weight:600;color:var(--ink)"><input type="checkbox" class="koX" value="${x.txId}" data-rest="${x.rest}" style="width:auto;min-height:0" ${x.txId === txId ? 'checked' : ''}> ${H(t.no)} · ${M(t.amount)} → <span dir="ltr">${H(t.recipient)}</span> · باقي ${M(x.rest)}</label>`; }).join('')}` : '<div class="muted">مفيش عمليات مفتوحة — هيتسجل رصيد له عندنا</div>';
    const sum = () => { const s = $$('.koX:checked').reduce((a, b) => a + (+b.dataset.rest), 0); if (s) $('#koA').value = C.fromP(s); }; $$('.koX').forEach(x => x.onchange = sum); if (txId) sum(); else { const b = (L.parties[val('koP')] || {}).balance || 0; if (b > 0) $('#koA').placeholder = 'المتبقي ' + C.fromP(b); } };
  $('#koP').onchange = drawOpen; drawOpen();
  $('#koGo').onclick = async () => { const amount = C.toP(val('koA')); if (amount <= 0) return toast('اكتب المبلغ', 'r'); const m = val('koM'); let left = amount; const alloc = $$('.koX:checked').map(x => { const a = Math.min(+x.dataset.rest, left); left -= a; return { txId: x.value, amount: a }; }).filter(a => a.amount > 0);
    await dispatch('coll.add', { id: C.uid(), partyId: val('koP'), amount, method: m === 'cash' ? 'cash' : 'wallet', walletId: m.startsWith('w:') ? m.slice(2) : null, date: new Date(val('koD')).toISOString(), alloc, note: val('koN') }); closeM(); toast('اتسجل التحصيل', 'g'); }; }
V.collect = () => { const L = C.ledgers(S), d = todayDay(), H2 = ST().dayStartHour; const rows = Object.values(S.customers).map(c => { const l = L.parties[c.id] || { balance: 0, open: [] }; const tt = Object.values(S.tx).filter(t => t.customerId === c.id && C.isEffective(t) && C.dayOf(t.executedAt, H2) === d); const kk = Object.values(S.colls).filter(k => k.partyId === c.id && !k.reversed && C.dayOf(k.date || k.createdAt, H2) === d);
    return { c, l, tAmt: tt.reduce((a, t) => a + t.amount, 0), tCom: tt.reduce((a, t) => a + (t.commission || 0), 0), kSum: kk.reduce((a, k) => a + k.amount, 0), cnt: tt.length }; }).filter(r => r.cnt || r.kSum || r.l.balance).sort((a, b) => b.l.balance - a.l.balance);
  const recent = Object.values(S.colls).sort((a, b) => (b.date || b.createdAt) > (a.date || a.createdAt) ? 1 : -1).slice(0, 25);
  return `<h1>${ic('cash')} تحصيلات اليوم <span class="sp"></span><button onclick="A.collect()">${ic('plus')}تسجيل تحصيل</button></h1>
  <div class="card sc"><table><tr><th>العميل / الوسيط</th><th>عمليات النهارده</th><th>عمولات</th><th>اتحصل النهارده</th><th>الرصيد المتبقي</th><th>الحالة</th><th></th></tr>${rows.map(r => `<tr><td><a href="#cust/${r.c.id}"><b>${H(r.c.name)}</b></a> <small class="muted">${H(r.c.type)}</small></td><td>${M(r.tAmt)} <small class="muted">(${N(r.cnt)})</small></td><td>${M(r.tCom)}</td><td>${M(r.kSum)}</td><td><b class="${r.l.balance > 0 ? 'neg' : 'pos'}">${M(r.l.balance)}</b></td><td>${r.l.balance <= 0 ? '<span class="tag">مسدد</span>' : r.l.paid ? '<span class="tag w">جزئي</span>' : '<span class="tag r">مفتوح</span>'}</td><td>${r.l.balance > 0 ? `<button class="w" onclick="A.collect('${r.c.id}')">${ic('cash')}تحصيل</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">مفيش حسابات مفتوحة</td></tr>'}</table></div>
  <div class="card sc"><b>آخر التحصيلات</b><table style="margin-top:8px"><tr><th>الوقت</th><th>من</th><th>المبلغ</th><th>الطريقة</th><th>ملاحظة</th><th></th></tr>${recent.map(k => `<tr ${k.reversed ? 'style="opacity:.5"' : ''}><td>${T(k.date || k.createdAt)}</td><td>${H((cust(k.partyId) || {}).name || '—')}</td><td>${M(k.amount)}</td><td>${k.method === 'wallet' ? H(wName(k.walletId)) : 'كاش'}</td><td>${H(k.note || '')}${k.reversed ? ' <span class="tag r">ملغي: ' + H(k.reverseReason) + '</span>' : ''}</td><td>${!k.reversed ? `<button class="g" onclick="A.revColl('${k.id}')">${ic('undo')}عكس</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">لسه مفيش</td></tr>'}</table></div>`; };
function revColl(id) { if (!need('balances')) return; prompt2('عكس التحصيل (بحركة عكسية — مش مسح)', 'السبب', async r => { await dispatch('coll.reverse', { id, reason: r }); toast('اتعكس', 'g'); }, { area: true }); }

/* =================== المحافظ والخزنة =================== */
